INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7046670, 1069536, 100393, '<td valign="top">This image has caused me to stop and pay attention. That means it is in my 7-10 voting band. (Voted earlier) <br/> <br/>Additionally, it is highly interesting/eclectic meaning it keeps me here long enough to offer a longer comment and a vote of 8 or more. <br/> <br/>This is one of my 8s - I like it. Furthermore I think it enriches the DPC collective portfolio. Put simply, I wish we saw more stuff like this. Let me tell you why it pushes all the right buttons for me: <br/> <br/>1. I love how you''ve created an impression that you were waiting for this moment - tapping your foot as you waited for the not-so-speedy vehicle to come into frame.<br/> <br/>2. Excellent spiky palm gives a sense of the exotic.<br/> <br/>3. The trailer brings us back to earth.<br/> <br/>4. The somewhat flat tones are perfectly matched to the mood of the scene.<br/> <br/>Good catch.</td>', 'This image has caused me to stop and pay attention. That means it is in my 7-10 voting band. (Voted earlier)  Additionally, it is highly interesting/eclectic meaning it keeps me here long enough to offer a longer comment and a vote of 8 or more.  This is one of my 8s - I like it. Furthermore I think it enriches the DPC collective portfolio. Put simply, I wish we saw more stuff like this. Let me tell you why it pushes all the right buttons for me:  1. I love how you''ve created an impression that you were waiting for this moment - tapping your foot as you waited for the not-so-speedy vehicle to come into frame. 2. Excellent spiky palm gives a sense of the exotic. 3. The trailer brings us back to earth. 4. The somewhat flat tones are perfectly matched to the mood of the scene. Good catch.', '2013-06-02 15:48:44.000000', NULL, 1),
(7046671, 1071097, 100393, '<td valign="top">This image has caused me to stop and pay attention. That means it is in my 7-10 voting band. (Voted earlier) <br/> <br/>Additionally, it is highly interesting/eclectic meaning it keeps me here long enough to offer a longer comment and a vote of 8 or more. <br/> <br/>This is one of my 8s - I like it. Furthermore I think it enriches the DPC collective portfolio. Put simply, I wish we saw more stuff like this. Let me tell you why it pushes all the right buttons for me: <br/> <br/>1. I like unconventional portraits and this fits the bill.<br/> <br/>2. Eclectic coloration that is really effective.<br/> <br/>3. The strange and eerie mood brought about by the dramatic light.<br/> <br/>4. The deep blacks - make the image almost like graphic art.<br/> <br/>Very interesting image.</td>', 'This image has caused me to stop and pay attention. That means it is in my 7-10 voting band. (Voted earlier)  Additionally, it is highly interesting/eclectic meaning it keeps me here long enough to offer a longer comment and a vote of 8 or more.  This is one of my 8s - I like it. Furthermore I think it enriches the DPC collective portfolio. Put simply, I wish we saw more stuff like this. Let me tell you why it pushes all the right buttons for me:  1. I like unconventional portraits and this fits the bill. 2. Eclectic coloration that is really effective. 3. The strange and eerie mood brought about by the dramatic light. 4. The deep blacks - make the image almost like graphic art. Very interesting image.', '2013-06-02 15:50:40.000000', NULL, 1),
