(7049445, 1071296, 152252, '<td valign="top">Awww! hope he didn''t get run over. The stuff on the shell looks really cool. Great perspective. I like that only the turtle is in focus. Nice composition. 10</td>', 'Awww! hope he didn''t get run over. The stuff on the shell looks really cool. Great perspective. I like that only the turtle is in focus. Nice composition. 10', '2013-06-07 21:37:50.000000', NULL, 1),
(7049446, 1068394, 152252, '<td valign="top">Oh wow, this fog, the subject and the tones are amazing. My top 3.</td>', 'Oh wow, this fog, the subject and the tones are amazing. My top 3.', '2013-06-07 21:39:02.000000', NULL, 1),
(7049447, 1071407, 109227, '<td valign="top">One of my favorites of the challenge; the colors, simplicity and composition are great. Hope it does well for you.</td>', 'One of my favorites of the challenge; the colors, simplicity and composition are great. Hope it does well for you.', '2013-06-07 21:43:13.000000', NULL, 1),
