(7049486, 1070704, 68503, '<td valign="top">this is an awesome capture but I think the processing killed it for me. Im seeing allot of saturation in her skin and it looks over-sharpened. Not sure if that was the look you were going for or not but it doesnt really work for me.</td>', 'this is an awesome capture but I think the processing killed it for me. Im seeing allot of saturation in her skin and it looks over-sharpened. Not sure if that was the look you were going for or not but it doesnt really work for me.', '2013-06-07 22:31:53.000000', NULL, 1),
(7049488, 1071140, 68503, '<td valign="top">time to replace the panels :)</td>', 'time to replace the panels :)', '2013-06-07 22:41:48.000000', NULL, 1),
(7049490, 1068981, 68503, '<td valign="top">Ok how many times is this bridge and waterfall going to be used on this site?? Just kidding still a great waterfall :)</td>', 'Ok how many times is this bridge and waterfall going to be used on this site?? Just kidding still a great waterfall :)', '2013-06-07 22:50:15.000000', NULL, 1),
