(7049493, 1068854, 65234, '<td valign="top">A battle-scarred warrior.  Not sure what I think about the texture overlay on the background.</td>', 'A battle-scarred warrior.  Not sure what I think about the texture overlay on the background.', '2013-06-07 22:57:51.000000', NULL, 1),
(7049494, 1070770, 65234, '<td valign="top">I think he wants to tell me a secret.  Like the backlighting, but I would have brightened his face a little more, I think.  Just a little so as not to spoil the mood.</td>', 'I think he wants to tell me a secret.  Like the backlighting, but I would have brightened his face a little more, I think.  Just a little so as not to spoil the mood.', '2013-06-07 22:59:47.000000', NULL, 1),
(7049495, 1070885, 65234, '<td valign="top">Love the light and perspective.  I feel like I''m spying from a neighboring tree on an intimate moment of birdie thought.</td>', 'Love the light and perspective.  I feel like I''m spying from a neighboring tree on an intimate moment of birdie thought.', '2013-06-07 23:01:28.000000', NULL, 1),
(7049496, 1071107, 65234, '<td valign="top">The expression and makeup are very 50s.  The tattoo, not so much ;-)</td>', 'The expression and makeup are very 50s.  The tattoo, not so much ;-)', '2013-06-07 23:03:00.000000', NULL, 1),
